    // If only scalar_types present, return max from there
    if array_types.is_empty() && !scalar_types.is_empty() {
        return Some(find_max_precedence_type(scalar_types));
    }

    // Both present
    let array_max = find_max_precedence_type(array_types);
    let scalar_max = find_max_precedence_type(scalar_types);

